"% Static margin and neutral point calculation
CLalpha = 4.8;       % lift-curve slope, /rad
Cmalpha = -1.1;      % pitching-moment slope, /rad
h_cg = 0.3;          % CG location as fraction of MAC

% Classical static longitudinal stability relations
static_margin = -Cmalpha / CLalpha;   % dimensionless (fraction of MAC)
h_n = h_cg + static_margin;          % neutral point, fraction of MAC

% Build result struct and write JSON
result = struct();
result.static_margin = static_margin;
result.h_n = h_n;

json_text = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_text);
fclose(fid);"
